#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int echo(const unsigned char *rec, size_t rec_len,
         unsigned char *out, size_t out_len) {
    if (rec_len < 2) return -1;                         /* no length field */
    size_t claimed = (size_t)(rec[0] << 8 | rec[1]);
    if (2 + claimed > rec_len) return -1;               /* the Heartbleed fix */
    if (claimed > out_len) return -1;                   /* and protect out */
    memcpy(out, rec + 2, claimed);
    return (int)claimed;
}

int main(void) {
    unsigned char *rec = malloc(6);
    memcpy(rec, "\x00\x14" "bird", 6);
    unsigned char out[64];
    printf("echo returned %d\n", echo(rec, 6, out, sizeof out));
    memcpy(rec, "\x00\x04" "bird", 6);
    printf("echo returned %d\n", echo(rec, 6, out, sizeof out));
    free(rec);
    return 0;
}

