struct item { uint32_t id; uint32_t qty; uint64_t price; };

struct item *load(uint32_t count) {
    if (count == 0 || count > 1000000) return NULL;   /* sane limit for this format */
    struct item *v = calloc(count, sizeof *v);       /* calloc checks count*size */
    if (!v) return NULL;
    for (uint32_t i = 0; i < count; i++)
        v[i].id = i;
    return v;
}

