static void session_end(struct session **sp) {
    free(*sp);
    *sp = NULL;                 /* no dangling copy left behind */
}

int main(void) {
    struct session *s = malloc(sizeof *s);
    if (!s) return 1;
    s->is_admin = 0;
    strcpy(s->user, "ana");
    session_end(&s);

    char *note = malloc(16);
