enum kind { NUM, STR };
struct value { enum kind kind; union { long num; const char *str; } u; };

void show(const struct value *v) {
    switch (v->kind) {               /* read the tag before the payload */
    case STR: printf("%s\n", v->u.str); break;
    case NUM: printf("%ld\n", v->u.num); break;
    default:  fprintf(stderr, "bad kind\n"); abort();
    }
}

